func (c *Controller) syncDynamicAnnotationsAndLabelsToVMI(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	if vm == nil || vm.Spec.Template == nil || vmi == nil || vmi.DeletionTimestamp != nil {
		return vmi, nil
	}

	patchSet := patch.New()
	newVmiAnnotations := maps.Clone(vmi.Annotations)
	if newVmiAnnotations == nil {
		newVmiAnnotations = map[string]string{}
	}
	newVmiLabels := maps.Clone(vmi.Labels)
	if newVmiLabels == nil {
		newVmiLabels = map[string]string{}
	}

	syncMap := func(patterns []string, vmMap, vmiMap, vmiOrigMap map[string]string, subPath string) {
		changed := false
		syncKey := func(key string) {
			vmVal, vmExists := vmMap[key]
			vmiVal, vmiExists := vmiMap[key]
			if vmExists == vmiExists && vmVal == vmiVal {
				return
			}
			changed = true
			if vmExists {
				vmiMap[key] = vmVal
			} else {
				delete(vmiMap, key)
			}
		}

		syncPrefix := func(prefix string) {
			visited := map[string]struct{}{}
			for key := range vmMap {
				if strings.HasPrefix(key, prefix) {
					visited[key] = struct{}{}
					syncKey(key)
				}
			}
			for key := range vmiMap {
				if strings.HasPrefix(key, prefix) {
					if _, ok := visited[key]; ok {
						continue
					}
					visited[key] = struct{}{}
					syncKey(key)
				}
			}
		}

		for _, pattern := range patterns {
			if pattern == "" {
				continue
			}
			if strings.HasSuffix(pattern, "*") {
				prefix := strings.TrimSuffix(pattern, "*")
				// Reject bare "*" to prevent accidental sync-all. Only prefix wildcards like "vendor.io/*" are supported.
				if prefix == "" {
					continue
				}
				syncPrefix(prefix)
				continue
			}
			syncKey(pattern)
		}

		if !changed {
			return
		}
